import {applyBroadFollowups052} from './broad-followups-052-replay.js';
import {attachCoverageReview} from './coverage-050-review.js';
import {applyCoverageExploration} from './coverage-050-replay.js';
import {modelMatchAudit} from './model-match-audit.js';
import {professionReplayState} from './profession-replay.js';
import {professionConfirmationState} from './profession-confirmation.js';
import {expandedInterestState} from './expanded-interest.js';
import {careerCheckSpec} from './career-check-questions.js';
import {careerCheckReadiness} from './career-check-readiness.js';
import {careerTitle} from './career-presentation.js';
import {educationRoutesFor} from './education-routes.js';
export function cohort049ReviewState(state,c){const s=structuredClone(state);for(const h of c.qualityReview?.holds||[]){for(const key of['coreWork','expandedInterests']){const a=s.profileJourney?.[key]?.[h.questionId];if(!a||a.response!=='yes')continue;s.profileJourney[key][h.questionId]={...a,inferenceConfidenceBeforeReview:a.confidence,confidence:'low',reviewHold:h.reason,reviewFollowup:h.followupQuestion};}}return s;}
export function cohort049FinalState(c){return applyCoverageExploration(cohort049ReviewState(expandedInterestState(professionConfirmationState(professionReplayState(c,c.professionReplay),c.professionInterest),c.expandedInterest),c),c.id);} 
export function cohort049Audit(c){
 const first=modelMatchAudit(c),replayed=professionReplayState(c,c.professionReplay),guided=cohort049ReviewState(professionConfirmationState(replayed,c.professionInterest),c),prior=modelMatchAudit({...c,experimentState:guided}),state=applyBroadFollowups052(cohort049FinalState(c),c.id),final=modelMatchAudit({...c,experimentState:state}),firstIds=new Set(first.top.map(r=>r.id)),finalIds=new Set(final.top.map(r=>r.id));
 const workQuestions=new Map((c.professionReplay?.comparisons||[]).flatMap(r=>(careerCheckSpec(r.id,{legacy:true})?.questions||[]).map(q=>[q.id,q]))),replayAnswers=(c.professionReplay?.answers||[]).map(a=>{const q=workQuestions.get(a.questionId);return{...a,prompt:q?.prompt||a.questionId,selectedTexts:a.selected.map(id=>{const o=q?.options.find(o=>o.id===id);return o?.text||o?.label||o?.title||id;})};});
 const comparisons=(c.professionReplay?.comparisons||[]).map(r=>{const spec=careerCheckSpec(r.id);return{id:r.id,title:careerTitle(spec.o),routes:educationRoutesFor(spec.o),questionIds:spec.questions.filter(q=>q.kind!=='core-work').map(q=>q.id),readiness:careerCheckReadiness(state,r.id),inFinalTop:finalIds.has(r.id)};});
 return attachCoverageReview({...final,cohort049:c.cohort049,qualityReview:c.qualityReview||null,reviewedOffers:[],degreeReview:{version:'0.49.0',priorTop:prior.top,priorPending:prior.needsConfirmation,priorOther:prior.other,changed:JSON.stringify(prior.top.map(r=>r.id))!==JSON.stringify(final.top.map(r=>r.id)),professions:c.expandedInterest?.professions||[],provenance:'New 0.49 profile. Current rules throughout; anonymous biography-based reflections frozen before rerun. No historical 0.46 offer is claimed. Frozen Yes answers with an editorial evidence hold remain low-confidence in the applied state until directly clarified; raw authored answers remain available.'},interestReview:{version:'0.49.0',priorTop:first.top,priorPending:first.needsConfirmation,answers:c.professionInterest?.professions||[],changed:JSON.stringify(first.top.map(r=>r.id))!==JSON.stringify(prior.top.map(r=>r.id)),provenance:'New simulation; two defining interests inferred from biography without career labels, scores or results. Unknown interests remain open. Applied evidence-review holds are separate from the unchanged authored answers.'},confirmationReview:{version:'0.49.0',priorTop:first.top,changed:JSON.stringify(first.top.map(r=>r.id))!==JSON.stringify(final.top.map(r=>r.id)),priorChanged:false,answers:[],provenance:'Current-rule baseline, before later comparison reflections.'},first:{top:first.top,needsConfirmation:first.needsConfirmation,other:first.other,sustaining:first.sustaining,explorations:first.explorations,matchPresentation:first.matchPresentation},replay:{status:comparisons.length?'completed':'not-offered',answerSHA256:c.cohort049?.followupSHA256||null,provenance:'0.49 initial answers, invited comparisons and later reflection answers frozen in that order. Simulated responses are not recorded student choices.',comparisons,answers:replayAnswers,added:final.top.filter(r=>!firstIds.has(r.id)).map(r=>({id:r.id,title:r.title,routes:r.routes})),removed:first.top.filter(r=>!finalIds.has(r.id)).map(r=>({id:r.id,title:r.title,routes:r.routes})),changed:JSON.stringify(first.top.map(r=>r.id))!==JSON.stringify(final.top.map(r=>r.id))}},state);
}
